        bne     L5060
        ldaa    >BitFlags049E
        bita    #$01
        bne     L4FFC
        ldaa    >BAUD
        anda    #$37
        cmpa    #$22
        beq     L4FFD
        ldaa    #$22
        staa    >BAUD
L4FFC:
        rts

L4FFD:
        ldaa    >SCSR
        bita    #$0E
        beq     L5008
        ldaa    >SCDR
        rts

L5008:
        bita    #$20
        bne     L501F
        brset   <DRBSerialMode,#$0F,L5014
        incb
        stab    <DRBSerialMode
        rts

L5014:
        brclr   <DRBSerialMode,#$30,L5060
        bclr    <DRBSerialMode,#$30
        clr     >DRBPointer1
        rts

L501F:
        ldaa    >SCDR
        staa    >SCDR
        andb    #$F0
        stab    <DRBSerialMode
        bitb    #$30
        bne     L504F
        cmpa    #$14
        beq     L5034
        bclr    <BitFlags6b,#$10
L5034:
        staa    <DRBPointer1
        clrb
        stab    <DRBPointer2
        stab    <DRBPointer3
        cmpa    #$25
        bhi     L5060
        suba    #$13
        bcs     L5060
        tab
        ldx     #DRBSerialToggles
        abx
        ldab    $00,x
        orab    <DRBSerialMode
        stab    <DRBSerialMode
        rts

L504F:
        bitb    #$20
        beq     L505A
        staa    <DRBPointer2
        andb    #$DF
        stab    <DRBSerialMode
        rts

L505A:
        staa    <DRBPointer3
        andb    #$CF
        stab    <DRBSerialMode
L5060:
        rts


